"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { useAuth } from "@/components/auth/AuthProvider";
import {
  ApiError,
  fetchAssessorQueue,
  type QueueSubmissionOut,
} from "@/lib/api";
import { ApiErrorAlert } from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { StatusBadge } from "@/components/layout/StatusBadge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

export default function ExpertQueuePage() {
  const params = useParams<{ competitionId: string }>();
  const competitionId = params.competitionId;
  const { me, status } = useAuth();

  const [items, setItems] = useState<QueueSubmissionOut[]>([]);
  const [error, setError] = useState<ApiError | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (status !== "authenticated" || !me?.id) return;
    let cancelled = false;
    async function load() {
      setLoading(true);
      setError(null);
      try {
        const out = await fetchAssessorQueue(me!.id, competitionId);
        if (cancelled) return;
        setItems(out.items ?? out.submissions ?? []);
      } catch (err) {
        if (!cancelled) {
          setError(
            err instanceof ApiError
              ? err
              : new ApiError(0, {
                  error: {
                    code: "HTTP_ERROR",
                    message: "Could not load assessor queue",
                    fields: [],
                    traceId: "",
                  },
                }),
          );
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    void load();
    return () => {
      cancelled = true;
    };
  }, [competitionId, me, status]);

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Assessor queue"
        description="Submissions assigned to you for this competition. Open a row to score against the rubric."
      />

      <p className="text-sm text-muted-foreground">
        Competition <span className="font-mono">{competitionId}</span>
      </p>

      <ApiErrorAlert error={error} />

      {loading ? (
        <p className="text-sm text-muted-foreground" role="status">
          Loading queue…
        </p>
      ) : null}

      <Card data-testid="expert-queue">
        <CardHeader>
          <CardTitle className="text-lg">Assigned submissions</CardTitle>
          <CardDescription>
            {items.length === 0 && !loading
              ? "No submissions in your queue for this competition."
              : `${items.length} item(s)`}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {items.length > 0 ? (
            <ul className="space-y-3">
              {items.map((item) => (
                <li
                  key={item.submissionId}
                  className="flex flex-col gap-2 rounded-md border border-border p-3 sm:flex-row sm:items-center sm:justify-between"
                  data-testid="expert-queue-item"
                >
                  <div>
                    <p className="font-medium" data-testid="expert-queue-anon">
                      {item.anonCode ?? "Anonymised submission"}
                    </p>
                    <p className="mt-1 font-mono text-xs text-muted-foreground">
                      {item.submissionId}
                    </p>
                    <div className="mt-2">
                      <StatusBadge status={item.state} />
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button asChild className="min-h-11">
                      <Link
                        href={`/expert/submissions/${item.submissionId}`}
                        data-testid="expert-queue-score"
                      >
                        Score
                      </Link>
                    </Button>
                    <Button asChild variant="outline" className="min-h-11">
                      <Link
                        href={`/expert/submissions/${item.submissionId}/moderation`}
                        data-testid="expert-queue-moderate"
                      >
                        Moderate
                      </Link>
                    </Button>
                  </div>
                </li>
              ))}
            </ul>
          ) : null}
        </CardContent>
      </Card>

      <p className="text-xs text-muted-foreground">
        <Link href="/expert" className="underline underline-offset-2">
          Back to assessor portal
        </Link>
      </p>
    </PageShell>
  );
}
